const headerFixture={rightNav:[{label:'其他',children:[{label:'保留'}]},{label:'我要加盟',to:'/franchising/intro',children:[{label:'加盟介紹',to:'/franchising/intro#introduction'}]}],copy:{custom:'保留'},cmsSettings:{visible:true}}
